1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"time"
12	)
13	
14	// 包裹状态。
15	const (
16		// statusInStation 表示包裹当前在某站点（已收件、已完成交接或回执失败回到出发站）。
17		statusInStation = "在站"
18		// statusDelivering 表示包裹已随某个配送批次出站，正在配送中。
19		statusDelivering = "配送中"
20		// statusSigned 表示包裹已签收（回执结果为签收）。
21		statusSigned = "已签收"
22		// statusFrozen 表示在站包裹因异常被冻结：站点不变，禁止交接、配送出站与整批退回。
23		statusFrozen = "异常冻结"
24	)
25	
26	// 回执结果。
27	const (
28		resultSigned = "签收"
29		resultFailed = "失败"
30	)
31	
32	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
33	type Event struct {
34		Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执 | 冻结 | 解除冻结 | 收回 | 续接 | 撤销回执
35		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站；冻结/解除冻结为包裹所在站点；收回/续接/撤销回执为批次出发站）
36		Time       time.Time `json:"time"`                 // 发生时间
37		Request    string    `json:"request,omitempty"`    // 交接/退回/回执/收回/续接/撤销请求号（收件、出站记录为空）
38		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）
39		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）、回执失败原因（仅失败回执有）、冻结原因（仅冻结记录有）、中止原因（仅收回记录有）、续接原因（仅续接记录有）或撤销原因（仅撤销回执记录有）
40		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）或被撤销的原回执请求号（仅撤销回执记录有）
41		Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执、收回、续接、撤销回执记录有；续接时为新批次号）
42		FromBatch  string    `json:"fromBatch,omitempty"`  // 续接原批次号（仅续接记录有）
43		Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站、续接记录有；续接时为新配送员）
44		Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
45		// Incident 为冻结/解除冻结记录的异常单号；解除冻结时另外用 Request 存解除请求号、Note 存处理说明。
46		Incident string `json:"incident,omitempty"`
47		Note     string `json:"note,omitempty"`
48	}
49	
50	// Parcel 是一件包裹的台账信息。
51	type Parcel struct {
52		ID         string    `json:"id"`
53		Station    string    `json:"station"`    // 当前归属站点
54		Status     string    `json:"status"`     // 当前状态
55		Registered time.Time `json:"registered"` // 收件时间
56		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
57	}
58	
59	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
60	type HandoffResult struct {
61		Request    string    `json:"request"`
62		From       string    `json:"from"`
63		To         string    `json:"to"`
64		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
65		Time       time.Time `json:"time"`
66		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
67	}
68	
69	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
70	type ReturnResult struct {
71		Request string    `json:"request"` // 退回请求号
72		Handoff string    `json:"handoff"` // 被退回的原交接请求号
73		From    string    `json:"from"`    // 退回源站（原交接目的站）
74		To      string    `json:"to"`      // 退回目的站（原交接源站）
75		Reason  string    `json:"reason"`
76		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
77		Time    time.Time `json:"time"`
78	}
79	
80	// ReceiptEntry 是批次内一件包裹的当前回执记录（被新回执取代的已撤销条目由
81	// 台账级 Receipts 结果表与撤销记录共同保留）。
82	type ReceiptEntry struct {
83		Request string    `json:"request"`          // 回执请求号
84		Result  string    `json:"result"`           // 签收 | 失败
85		Reason  string    `json:"reason,omitempty"` // 失败原因（仅失败回执有）
86		Time    time.Time `json:"time"`
87		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；撤销后该条不再计入有效回执。
88		RevokedBy string `json:"revokedBy,omitempty"`
89	}
90	
91	// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
92	// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
93	type BatchResult struct {
94		Batch    string                   `json:"batch"`
95		Station  string                   `json:"station"`  // 出发站
96		Courier  string                   `json:"courier"`  // 配送员
97		Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
98		Time     time.Time                `json:"time"`     // 出站时间
99		Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
100		// AbortedBy 为中止该批次的中止请求号（未中止为空）；中止永久生效，批次不得复用。
101		AbortedBy string `json:"abortedBy,omitempty"`
102		// TransferredBy 为把该批次关闭为“已转交”的续接请求号（未转交为空）；
103		// 转交永久生效，与中止互斥，批次不得复用。
104		TransferredBy string `json:"transferredBy,omitempty"`
105		// RelayedFrom 与 RelayRequest 仅对续接创建的新批次有效：分别记录来源批次号
106		// 与创建本批次的续接请求号（普通出站批次为空）。
107		RelayedFrom  string `json:"relayedFrom,omitempty"`
108		RelayRequest string `json:"relayRequest,omitempty"`
109	}
110	
111	// Effective 返回批次当前有效（未撤销）的回执数量。
112	func (b *BatchResult) Effective() int {
113		n := 0
114		for _, e := range b.Receipts {
115			if e != nil && e.RevokedBy == "" {
116				n++
117			}
118		}
119		return n
120	}
121	
122	// Done 报告批次是否已完成（全部成员均有未撤销的有效回执）。
123	func (b *BatchResult) Done() bool { return b.Effective() == len(b.Parcels) }
124	
125	// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
126	// 回执结果永久保留：即使之后被撤销，回执请求号也不删除、不释放。
127	type ReceiptResult struct {
128		Request string    `json:"request"` // 回执请求号
129		Batch   string    `json:"batch"`   // 所属配送批次号
130		Parcel  string    `json:"parcel"`  // 包裹编号
131		Result  string    `json:"result"`  // 签收 | 失败
132		Reason  string    `json:"reason,omitempty"`
133		Time    time.Time `json:"time"`
134		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；每条回执只能被撤销一次。
135		RevokedBy string `json:"revokedBy,omitempty"`
136	}
137	
138	// FreezeResult 记录一次成功的异常冻结，用于异常单号去重与结果重放。
139	// 异常单号标识一次异常，解除后也不能复用；失败的首次冻结不占用异常单号。
140	type FreezeResult struct {
141		Incident string    `json:"incident"` // 异常单号
142		Parcel   string    `json:"parcel"`   // 被冻结的包裹编号
143		Station  string    `json:"station"`  // 冻结时包裹所在站点（冻结与解除期间均不变）
144		Reason   string    `json:"reason"`   // 清理后的冻结原因
145		Time     time.Time `json:"time"`     // 冻结时间
146		// ReleasedBy 为解除该异常单的解除请求号（未解除为空）；解除后异常单永久保留、不得复用。
147		ReleasedBy string `json:"releasedBy,omitempty"`
148	}
149	
150	// UnfreezeResult 记录一次成功的解除冻结，用于解除请求号去重与结果重放。
151	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名；失败的首次解除不占用请求号。
152	type UnfreezeResult struct {
153		Request  string    `json:"request"`  // 解除请求号
154		Incident string    `json:"incident"` // 被解除的异常单号
155		Parcel   string    `json:"parcel"`   // 对应包裹编号
156		Note     string    `json:"note"`     // 清理后的处理说明
157		Time     time.Time `json:"time"`     // 解除时间
158	}
159	
160	// AbortResult 记录一次成功的配送批次中止，用于中止请求号去重与结果重放。
161	// 中止表示配送员已将该批次全部尚未回执的包裹实物收回出发站：批次永久关闭，
162	// 原成员顺序、配送员与出站时间保留不变，已回执成员及其回执完全保留。
163	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名；失败的首次中止不占用请求号。
164	type AbortResult struct {
165		Request string    `json:"request"` // 中止请求号
166		Batch   string    `json:"batch"`   // 被中止的配送批次号
167		Station string    `json:"station"` // 出发站（收回目的站，取自原批次）
168		Reason  string    `json:"reason"`  // 清理后的中止原因
169		Parcels []string  `json:"parcels"` // 首次收回的未回执包裹，按原批次成员顺序
170		Time    time.Time `json:"time"`    // 中止时间
171	}
172	
173	// TransferResult 记录一次成功的配送途中整批续接，用于续接请求号去重与结果重放。
174	// 续接表示原配送员把原批次全部尚未回执的包裹在配送途中交给另一配送员：
175	// 新批次按原顺序接纳全部未回执件继续配送，包裹保持“配送中”及原站点，
176	// 原批次永久关闭为“已转交”。续接请求号独立去重，可与批次号、包裹号及其他
177	// 业务编号同名；失败的首次续接不占用请求号。
178	type TransferResult struct {
179		Request     string    `json:"request"`     // 续接请求号
180		FromBatch   string    `json:"fromBatch"`   // 原批次号
181		ToBatch     string    `json:"toBatch"`     // 新批次号
182		Station     string    `json:"station"`     // 出发站（沿用原批次）
183		FromCourier string    `json:"fromCourier"` // 原配送员（取自原批次）
184		ToCourier   string    `json:"toCourier"`   // 新配送员
185		Reason      string    `json:"reason"`      // 清理后的续接原因
186		Parcels     []string  `json:"parcels"`     // 首次转交集合（原批次未回执成员，按原成员顺序）
187		Time        time.Time `json:"time"`        // 接手时间
188	}
189	
190	// RevokeResult 记录一次成功的误录回执撤销，用于撤销请求号去重与结果重放。
191	// 撤销只更正台账：经核实包裹实际仍由原配送员配送，撤销错误的签收或失败登记，
192	// 不收回实物。原回执结果与轨迹永久保留并标记已撤销，回执请求号不删除也不释放。
193	// 撤销请求号独立去重，可与批次号、包裹号、回执请求号及其他业务编号同名；
194	// 失败的首次撤销不占用请求号。
195	type RevokeResult struct {
196		Request string    `json:"request"` // 撤销请求号
197		Receipt string    `json:"receipt"` // 被撤销的原回执请求号
198		Batch   string    `json:"batch"`   // 所属配送批次号（取自原回执，不可另选）
199		Parcel  string    `json:"parcel"`  // 包裹编号（取自原回执，不可另选）
200		Reason  string    `json:"reason"`  // 清理后的撤销原因
201		Time    time.Time `json:"time"`    // 撤销时间
202	}
203	
204	// ledgerFile 是本地数据文件的磁盘结构。
205	type ledgerFile struct {
206		Version   int                        `json:"version"`
207		Parcels   map[string]*Parcel         `json:"parcels"`
208		Handoffs  map[string]*HandoffResult  `json:"handoffs"`
209		Returns   map[string]*ReturnResult   `json:"returns"`
210		Batches   map[string]*BatchResult    `json:"batches"`
211		Receipts  map[string]*ReceiptResult  `json:"receipts"`
212		Freezes   map[string]*FreezeResult   `json:"freezes"`   // 以异常单号为键（含已解除的异常单，永久保留）
213		Unfreezes map[string]*UnfreezeResult `json:"unfreezes"` // 以解除请求号为键
214		Aborts    map[string]*AbortResult    `json:"aborts"`    // 以中止请求号为键
215		Transfers map[string]*TransferResult `json:"transfers"` // 以续接请求号为键
216		Revokes   map[string]*RevokeResult   `json:"revokes"`   // 以撤销请求号为键
217	}
218	
219	// Store 是一个数据文件对应的包裹站点交接台账。
220	type Store struct {
221		path string
222		data ledgerFile
223	}
224	
225	var (
226		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
227		ErrCorrupt = errors.New("数据文件已损坏")
228		// ErrNotFound 表示包裹编号在台账中不存在。
229		ErrNotFound = errors.New("包裹不存在")
230	)
231	
232	// Open 打开（或在文件不存在时建立）一个本地台账。
233	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
234	func Open(path string) (*Store, error) {
235		s := &Store{path: path}
236		raw, err := os.ReadFile(path)
237		if err != nil {
238			if os.IsNotExist(err) {
239				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
240					Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{},
241					Freezes: map[string]*FreezeResult{}, Unfreezes: map[string]*UnfreezeResult{}, Aborts: map[string]*AbortResult{},
242					Transfers: map[string]*TransferResult{}, Revokes: map[string]*RevokeResult{}}
243				return s, nil
244			}
245			return nil, fmt.Errorf("读取数据文件失败: %w", err)
246		}
247		if len(bytes.TrimSpace(raw)) == 0 {
248			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
249		}
250		if err := json.Unmarshal(raw, &s.data); err != nil {
251			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
252		}
253		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
254			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
255		}
256		// 早期版本的数据文件没有 returns/batches/receipts/freeze/abort/revoke 相关字段：按空表处理，无需手工修改。
257		if s.data.Returns == nil {
258			s.data.Returns = map[string]*ReturnResult{}
259		}
260		if s.data.Batches == nil {
261			s.data.Batches = map[string]*BatchResult{}
262		}
263		if s.data.Receipts == nil {
264			s.data.Receipts = map[string]*ReceiptResult{}
265		}
266		if s.data.Freezes == nil {
267			s.data.Freezes = map[string]*FreezeResult{}
268		}
269		if s.data.Unfreezes == nil {
270			s.data.Unfreezes = map[string]*UnfreezeResult{}
271		}
272		if s.data.Aborts == nil {
273			s.data.Aborts = map[string]*AbortResult{}
274		}
275		if s.data.Transfers == nil {
276			s.data.Transfers = map[string]*TransferResult{}
277		}
278		if s.data.Revokes == nil {
279			s.data.Revokes = map[string]*RevokeResult{}
280		}
281		for _, b := range s.data.Batches {
282			if b != nil && b.Receipts == nil {
283				b.Receipts = map[string]*ReceiptEntry{}
284			}
285		}
286		if err := s.data.validate(); err != nil {
287			return nil, err
288		}
289		return s, nil
290	}
291	
292	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
293	func (l *ledgerFile) validate() error {
294		for id, p := range l.Parcels {
295			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
296				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
297			}
298			switch p.Status {
299			case statusInStation, statusDelivering, statusSigned, statusFrozen:
300			default:
301				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
302			}
303			for i, e := range p.Trail {
304				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
305					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
306				}
307				if e.Op == "退回" {
308					if e.Request == "" || e.Reason == "" || e.From == "" {
309						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
310					}
311					if _, ok := l.Handoffs[e.RefRequest]; !ok {
312						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
313					}
314				}
315				if e.Op == "出站" {
316					if e.Batch == "" || e.Courier == "" {
317						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
318					}
319					if _, ok := l.Batches[e.Batch]; !ok {
320						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
321					}
322				}
323				if e.Op == "回执" {
324					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
325						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
326					}
327					if e.Result == resultFailed && e.Reason == "" {
328						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
329					}
330					if _, ok := l.Batches[e.Batch]; !ok {
331						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
332					}
333				}
334				if e.Op == "撤销回执" {
335					if e.Batch == "" || e.Request == "" || e.RefRequest == "" || e.Reason == "" {
336						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹缺少批次号、撤销请求号、原回执请求号或原因", ErrCorrupt, id, i+1)
337					}
338					b, ok := l.Batches[e.Batch]
339					if !ok {
340						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
341					}
342					if e.Station != b.Station {
343						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹的站点 %q 与批次 %q 出发站 %q 不一致",
344							ErrCorrupt, id, i+1, e.Station, e.Batch, b.Station)
345					}
346					rv, ok := l.Revokes[e.Request]
347					if !ok {
348						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的撤销请求 %q", ErrCorrupt, id, i+1, e.Request)
349					}
350					if rv.Receipt != e.RefRequest || rv.Batch != e.Batch || rv.Parcel != id || rv.Reason != e.Reason || !rv.Time.Equal(e.Time) {
351						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹与撤销请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
352					}
353				}
354				if e.Op == "收回" {
355					if e.Batch == "" || e.Request == "" || e.Reason == "" {
356						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹缺少批次号、中止请求号或原因", ErrCorrupt, id, i+1)
357					}
358					a, ok := l.Aborts[e.Request]
359					if !ok {
360						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹引用了不存在的中止请求 %q", ErrCorrupt, id, i+1, e.Request)
361					}
362					if a.Batch != e.Batch || a.Station != e.Station || a.Reason != e.Reason || !a.Time.Equal(e.Time) {
363						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹与中止请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
364					}
365					inAbort := false
366					for _, pid := range a.Parcels {
367						if pid == id {
368							inAbort = true
369							break
370						}
371					}
372					if !inAbort {
373						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹不在中止请求 %q 的收回集合中", ErrCorrupt, id, i+1, e.Request)
374					}
375				}
376				if e.Op == "续接" {
377					if e.Batch == "" || e.FromBatch == "" || e.Courier == "" || e.Request == "" || e.Reason == "" {
378						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹缺少新批次号、原批次号、新配送员、续接请求号或原因", ErrCorrupt, id, i+1)
379					}
380					t, ok := l.Transfers[e.Request]
381					if !ok {
382						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹引用了不存在的续接请求 %q", ErrCorrupt, id, i+1, e.Request)
383					}
384					if t.FromBatch != e.FromBatch || t.ToBatch != e.Batch || t.ToCourier != e.Courier ||
385						t.Station != e.Station || t.Reason != e.Reason || !t.Time.Equal(e.Time) {
386						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹与续接请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
387					}
388					inTransfer := false
389					for _, pid := range t.Parcels {
390						if pid == id {
391							inTransfer = true
392							break
393						}
394					}
395					if !inTransfer {
396						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹不在续接请求 %q 的转交集合中", ErrCorrupt, id, i+1, e.Request)
397					}
398				}
399				if e.Op == "冻结" {
400					if e.Incident == "" || e.Reason == "" {
401						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹缺少异常单号或原因", ErrCorrupt, id, i+1)
402					}
403					f, ok := l.Freezes[e.Incident]
404					if !ok {
405						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
406					}
407					if f.Parcel != id || f.Reason != e.Reason || f.Station != e.Station || !f.Time.Equal(e.Time) {
408						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹与异常单 %q 记录不一致", ErrCorrupt, id, i+1, e.Incident)
409					}
410				}
411				if e.Op == "解除冻结" {
412					if e.Incident == "" || e.Request == "" || e.Note == "" {
413						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹缺少异常单号、解除请求号或处理说明", ErrCorrupt, id, i+1)
414					}
415					f, ok := l.Freezes[e.Incident]
416					if !ok {
417						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
418					}
419					if f.Parcel != id || f.Station != e.Station || f.ReleasedBy != e.Request {
420						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与异常单 %q 不匹配", ErrCorrupt, id, i+1, e.Incident)
421					}
422					u, ok := l.Unfreezes[e.Request]
423					if !ok || u.Incident != e.Incident || u.Parcel != id || u.Note != e.Note || !u.Time.Equal(e.Time) {
424						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与解除请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
425					}
426				}
427			}
428		}
429		for req, h := range l.Handoffs {
430			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
431				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
432			}
433			for _, id := range h.Parcels {
434				if _, ok := l.Parcels[id]; !ok {
435					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
436				}
437			}
438			if h.ReturnedBy != "" {
439				r, ok := l.Returns[h.ReturnedBy]
440				if !ok || r.Handoff != req {
441					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
442				}
443			}
444		}
445		for req, r := range l.Returns {
446			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
447				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
448				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
449			}
450			h, ok := l.Handoffs[r.Handoff]
451			if !ok {
452				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
453			}
454			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
455				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
456			}
457			for _, id := range r.Parcels {
458				if _, ok := l.Parcels[id]; !ok {
459					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
460				}
461			}
462		}
463		for id, b := range l.Batches {
464			if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
465				return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
466			}
467			seen := make(map[string]bool, len(b.Parcels))
468			for _, pid := range b.Parcels {
469				if seen[pid] {
470					return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
471				}
472				seen[pid] = true
473				if _, ok := l.Parcels[pid]; !ok {
474					return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
475				}
476			}
477			for pid, e := range b.Receipts {
478				if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
479					(e.Result != resultSigned && e.Result != resultFailed) ||
480					(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
481					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
482				}
483				rc, ok := l.Receipts[e.Request]
484				if !ok || rc.Batch != id || rc.Parcel != pid {
485					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
486				}
487				if e.RevokedBy != rc.RevokedBy {
488					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执条目与回执请求号 %q 的撤销标记不一致", ErrCorrupt, id, pid, e.Request)
489				}
490			}
491			if b.AbortedBy != "" {
492				a, ok := l.Aborts[b.AbortedBy]
493				if !ok || a.Batch != id {
494					return fmt.Errorf("%w: 批次 %q 标记的中止请求号 %q 无法对应", ErrCorrupt, id, b.AbortedBy)
495				}
496			}
497			if b.TransferredBy != "" {
498				if b.AbortedBy != "" {
499					return fmt.Errorf("%w: 批次 %q 不能同时标记中止与转交", ErrCorrupt, id)
500				}
501				t, ok := l.Transfers[b.TransferredBy]
502				if !ok || t.FromBatch != id {
503					return fmt.Errorf("%w: 批次 %q 标记的续接请求号 %q 无法对应", ErrCorrupt, id, b.TransferredBy)
504				}
505			}
506			if b.RelayedFrom != "" {
507				t, ok := l.Transfers[b.RelayRequest]
508				if !ok || t.ToBatch != id || t.FromBatch != b.RelayedFrom {
509					return fmt.Errorf("%w: 批次 %q 标记的续接来源（原批次=%q 续接请求号=%q）无法对应",
510						ErrCorrupt, id, b.RelayedFrom, b.RelayRequest)
511				}
512			} else if b.RelayRequest != "" {
513				return fmt.Errorf("%w: 批次 %q 标记了续接请求号 %q 但缺少来源批次", ErrCorrupt, id, b.RelayRequest)
514			}
515		}
516		for req, rc := range l.Receipts {
517			if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
518				(rc.Result != resultSigned && rc.Result != resultFailed) ||
519				(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
520				return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
521			}
522			b, ok := l.Batches[rc.Batch]
523			if !ok {
524				return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
525			}
526			// 每件包裹的当前回执条目一旦建立只会被新回执取代、不会删除，
527			// 因此该件在批次内必须始终有一条回执条目。
528			e, cur := b.Receipts[rc.Parcel]
529			if !cur {
530				return fmt.Errorf("%w: 回执请求号 %q 在批次 %q 中缺少包裹 %q 的回执条目", ErrCorrupt, req, rc.Batch, rc.Parcel)
531			}
532			if rc.RevokedBy == "" {
533				// 未撤销回执必须仍是该件在该批次的当前有效回执。
534				if e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != "" {
535					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
536				}
537				continue
538			}
539			// 已撤销回执：撤销关联必须存在且回指该回执。
540			rv, ok := l.Revokes[rc.RevokedBy]
541			if !ok || rv.Receipt != req {
542				return fmt.Errorf("%w: 回执请求号 %q 标记的撤销请求号 %q 无法对应", ErrCorrupt, req, rc.RevokedBy)
543			}
544			if e.Request == req {
545				// 该件之后未重新回执：批次内条目必须同内容并同样标记撤销。
546				if e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != rc.RevokedBy {
547					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
548				}
549			}
550			// 该件之后已用新请求号重新回执：当前条目属于新回执，由其自身校验。
551		}
552		// 撤销：每条撤销必须对应一条已撤销回执，批次、包裹一致，且包裹轨迹中有
553		// 与该撤销请求一致的撤销回执记录；撤销关联缺失或不一致即损坏。
554		for req, rv := range l.Revokes {
555			if rv == nil || req != rv.Request || rv.Receipt == "" || rv.Batch == "" || rv.Parcel == "" ||
556				rv.Reason == "" || rv.Time.IsZero() {
557				return fmt.Errorf("%w: 撤销请求号 %q 的撤销结果不完整", ErrCorrupt, req)
558			}
559			rc, ok := l.Receipts[rv.Receipt]
560			if !ok {
561				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的原回执 %q", ErrCorrupt, req, rv.Receipt)
562			}
563			if rc.RevokedBy != req {
564				return fmt.Errorf("%w: 撤销请求号 %q 与原回执 %q 的撤销标记不一致", ErrCorrupt, req, rv.Receipt)
565			}
566			if rc.Batch != rv.Batch || rc.Parcel != rv.Parcel {
567				return fmt.Errorf("%w: 撤销请求号 %q 的批次或包裹与原回执 %q 不一致", ErrCorrupt, req, rv.Receipt)
568			}
569			p, ok := l.Parcels[rv.Parcel]
570			if !ok {
571				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, rv.Parcel)
572			}
573			found := false
574			for _, e := range p.Trail {
575				if e.Op == "撤销回执" && e.Request == req {
576					found = true
577					break
578				}
579			}
580			if !found {
581				return fmt.Errorf("%w: 撤销请求号 %q 的包裹 %q 缺少对应的撤销回执轨迹", ErrCorrupt, req, rv.Parcel)
582			}
583		}
584		// 中止：收回集合必须恰为原批次的未回执成员（按原成员顺序，已撤销回执不计入
585		// 有效回执），且每件收回包裹的轨迹中都有与该中止请求一致的收回记录；
586		// 中止记录与收回轨迹不一致即损坏。
587		for req, a := range l.Aborts {
588			if a == nil || req != a.Request || a.Batch == "" || a.Station == "" || a.Reason == "" ||
589				len(a.Parcels) == 0 || a.Time.IsZero() {
590				return fmt.Errorf("%w: 中止请求号 %q 的中止结果不完整", ErrCorrupt, req)
591			}
592			b, ok := l.Batches[a.Batch]
593			if !ok {
594				return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, a.Batch)
595			}
596			if b.AbortedBy != req {
597				return fmt.Errorf("%w: 中止请求号 %q 与批次 %q 的中止标记不一致", ErrCorrupt, req, a.Batch)
598			}
599			if a.Station != b.Station {
600				return fmt.Errorf("%w: 中止请求号 %q 的站点 %q 与批次 %q 出发站 %q 不一致", ErrCorrupt, req, a.Station, a.Batch, b.Station)
601			}
602			expect := make([]string, 0, len(b.Parcels))
603			for _, pid := range b.Parcels {
604				if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
605					expect = append(expect, pid)
606				}
607			}
608			if len(expect) != len(a.Parcels) {
609				return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
610			}
611			for i := range expect {
612				if expect[i] != a.Parcels[i] {
613					return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
614				}
615			}
616			for _, pid := range a.Parcels {
617				p, ok := l.Parcels[pid]
618				if !ok {
619					return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
620				}
621				found := false
622				for _, e := range p.Trail {
623					if e.Op == "收回" && e.Request == req {
624						found = true
625						break
626					}
627				}
628				if !found {
629					return fmt.Errorf("%w: 中止请求号 %q 的收回包裹 %q 缺少对应的收回轨迹", ErrCorrupt, req, pid)
630				}
631			}
632		}
633		// 续接：转交集合必须恰为原批次的未回执成员（按原成员顺序），新批次必须由该续接
634		// 创建且成员、站点、配送员、接手时间与之一致；每件转交包裹的轨迹中都有与该
635		// 续接请求一致的续接记录；续接记录与批次及轨迹不一致即损坏。
636		for req, t := range l.Transfers {
637			if t == nil || req != t.Request || t.FromBatch == "" || t.ToBatch == "" || t.Station == "" ||
638				t.FromCourier == "" || t.ToCourier == "" || t.FromCourier == t.ToCourier ||
639				t.Reason == "" || len(t.Parcels) == 0 || t.Time.IsZero() {
640				return fmt.Errorf("%w: 续接请求号 %q 的续接结果不完整", ErrCorrupt, req)
641			}
642			fb, ok := l.Batches[t.FromBatch]
643			if !ok {
644				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的原批次 %q", ErrCorrupt, req, t.FromBatch)
645			}
646			if fb.TransferredBy != req {
647				return fmt.Errorf("%w: 续接请求号 %q 与原批次 %q 的转交标记不一致", ErrCorrupt, req, t.FromBatch)
648			}
649			if fb.Station != t.Station || fb.Courier != t.FromCourier {
650				return fmt.Errorf("%w: 续接请求号 %q 的站点或原配送员与原批次 %q 不一致", ErrCorrupt, req, t.FromBatch)
651			}
652			nb, ok := l.Batches[t.ToBatch]
653			if !ok {
654				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的新批次 %q", ErrCorrupt, req, t.ToBatch)
655			}
656			if nb.RelayedFrom != t.FromBatch || nb.RelayRequest != req {
657				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的来源标记不一致", ErrCorrupt, req, t.ToBatch)
658			}
659			if nb.Station != t.Station || nb.Courier != t.ToCourier || !nb.Time.Equal(t.Time) {
660				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的站点、配送员或接手时间不一致", ErrCorrupt, req, t.ToBatch)
661			}
662			expect := make([]string, 0, len(fb.Parcels))
663			for _, pid := range fb.Parcels {
664				if e, done := fb.Receipts[pid]; !done || e.RevokedBy != "" {
665					expect = append(expect, pid)
666				}
667			}
668			if !sameOrder(expect, t.Parcels) || !sameOrder(t.Parcels, nb.Parcels) {
669				return fmt.Errorf("%w: 续接请求号 %q 的转交集合与原批次 %q 的未回执成员或新批次 %q 的成员不一致",
670					ErrCorrupt, req, t.FromBatch, t.ToBatch)
671			}
672			for _, pid := range t.Parcels {
673				p, ok := l.Parcels[pid]
674				if !ok {
675					return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
676				}
677				found := false
678				for _, e := range p.Trail {
679					if e.Op == "续接" && e.Request == req {
680						found = true
681						break
682					}
683				}
684				if !found {
685					return fmt.Errorf("%w: 续接请求号 %q 的转交包裹 %q 缺少对应的续接轨迹", ErrCorrupt, req, pid)
686				}
687			}
688		}
689		// 冻结/解除冻结：先遍历轨迹核对冻结与解除必须成对出现、顺序正确，
690		// 再核对两张结果表与包裹当前状态的对应关系。
691		openIncident := make(map[string]string) // 包裹 -> 当前未解除的异常单号（由轨迹推导）
692		for id, p := range l.Parcels {
693			var open string
694			for i, e := range p.Trail {
695				switch e.Op {
696				case "冻结":
697					if open != "" {
698						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结时异常单 %q 尚未解除，一件包裹同时只能有一张未解除异常单",
699							ErrCorrupt, id, i+1, open)
700					}
701					open = e.Incident
702				case "解除冻结":
703					if open != e.Incident {
704						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除的异常单 %q 与当前冻结 %q 不匹配",
705							ErrCorrupt, id, i+1, e.Incident, open)
706					}
707					open = ""
708				}
709			}
710			if p.Status == statusFrozen && open == "" {
711				return fmt.Errorf("%w: 包裹 %q 当前为异常冻结，但轨迹中没有未解除的冻结记录", ErrCorrupt, id)
712			}
713			if p.Status != statusFrozen && open != "" {
714				return fmt.Errorf("%w: 包裹 %q 当前状态为 %q，但异常单 %q 尚未解除", ErrCorrupt, id, p.Status, open)
715			}
716			if open != "" {
717				openIncident[id] = open
718			}
719		}
720		for no, f := range l.Freezes {
721			if f == nil || no != f.Incident || f.Parcel == "" || f.Station == "" || f.Reason == "" || f.Time.IsZero() {
722				return fmt.Errorf("%w: 异常单号 %q 的冻结结果不完整", ErrCorrupt, no)
723			}
724			p, ok := l.Parcels[f.Parcel]
725			if !ok {
726				return fmt.Errorf("%w: 异常单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, f.Parcel)
727			}
728			if f.ReleasedBy == "" && p.Station != f.Station {
729				return fmt.Errorf("%w: 异常单 %q 记录的站点 %q 与包裹 %q 当前站点 %q 不一致",
730					ErrCorrupt, no, f.Station, f.Parcel, p.Station)
731			}
732			if f.ReleasedBy != "" {
733				u, ok := l.Unfreezes[f.ReleasedBy]
734				if !ok || u.Incident != no || u.Parcel != f.Parcel {
735					return fmt.Errorf("%w: 异常单 %q 标记的解除请求号 %q 无法对应", ErrCorrupt, no, f.ReleasedBy)
736				}
737			}
738		}
739		activeByParcel := make(map[string]string)
740		for req, u := range l.Unfreezes {
741			if u == nil || req != u.Request || u.Incident == "" || u.Parcel == "" || u.Note == "" || u.Time.IsZero() {
742				return fmt.Errorf("%w: 解除请求号 %q 的解除结果不完整", ErrCorrupt, req)
743			}
744			f, ok := l.Freezes[u.Incident]
745			if !ok {
746				return fmt.Errorf("%w: 解除请求号 %q 引用了不存在的异常单 %q", ErrCorrupt, req, u.Incident)
747			}
748			if f.Parcel != u.Parcel {
749				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 对应的包裹不一致", ErrCorrupt, req, u.Incident)
750			}
751			if f.ReleasedBy != req {
752				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 的解除标记不一致", ErrCorrupt, req, u.Incident)
753			}
754		}
755		for no, f := range l.Freezes {
756			if f.ReleasedBy != "" {
757				continue
758			}
759			if other, dup := activeByParcel[f.Parcel]; dup {
760				return fmt.Errorf("%w: 包裹 %q 同时存在两张未解除异常单 %q 与 %q", ErrCorrupt, f.Parcel, other, no)
761			}
762			activeByParcel[f.Parcel] = no
763			if openIncident[f.Parcel] != no {
764				return fmt.Errorf("%w: 包裹 %q 当前冻结对应的异常单应为 %q，与未解除异常单 %q 不匹配",
765					ErrCorrupt, f.Parcel, openIncident[f.Parcel], no)
766			}
767			if p := l.Parcels[f.Parcel]; p.Status != statusFrozen {
768				return fmt.Errorf("%w: 异常单 %q 未解除，但包裹 %q 当前状态为 %q", ErrCorrupt, no, f.Parcel, p.Status)
769			}
770		}
771		return nil
772	}
