774	// Register 执行单件收件登记并将结果整体落盘。
775	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
776		if _, ok := s.data.Parcels[id]; ok {
777			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
778		}
779		p := &Parcel{
780			ID:         id,
781			Station:    station,
782			Status:     statusInStation,
783			Registered: now,
784			Trail: []Event{{
785				Op:      "收件",
786				Station: station,
787				Time:    now,
788			}},
789		}
790		s.data.Parcels[id] = p
791		if err := s.save(); err != nil {
792			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
793			return nil, err
794		}
795		return p, nil
796	}
