819	// Handoff 提交一次多件包裹的站点交接。
820	//
821	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
822	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
823	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
824	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
825	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
826		if saved, ok := s.data.Handoffs[request]; ok {
827			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
828				return saved, true, nil
829			}
830			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
831		}
832	
833		// 首次提交：先做全部校验，任何一件不满足都整体失败。
834		for _, id := range parcels {
835			p, ok := s.data.Parcels[id]
836			if !ok {
837				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
838			}
839			if p.Station != from {
840				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
841			}
842			if inc := activeFreeze(p); inc != "" {
843				return nil, false, fmt.Errorf("交接失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批交接拒绝，整次交接未执行", id, inc)
844			}
845			if p.Status != statusInStation {
846				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
847			}
848		}
849	
850		res := &HandoffResult{
851			Request: request,
852			From:    from,
853			To:      to,
854			Parcels: append([]string(nil), parcels...),
855			Time:    now,
856		}
857		s.data.Handoffs[request] = res
858	
859		// 记录旧值，落盘失败时整体回滚。
860		prev := make(map[string]struct {
861			station string
862			trail   []Event
863		}, len(parcels))
864		for _, id := range parcels {
865			p := s.data.Parcels[id]
866			prev[id] = struct {
867				station string
868				trail   []Event
869			}{p.Station, append([]Event(nil), p.Trail...)}
870			p.Station = to
871			p.Status = statusInStation
872			p.Trail = append(p.Trail, Event{
873				Op:      "交接",
874				Station: to,
875				Request: request,
876				Time:    now,
877			})
878		}
879	
880		if err := s.save(); err != nil {
881			delete(s.data.Handoffs, request)
882			for id, old := range prev {
883				p := s.data.Parcels[id]
884				p.Station = old.station
885				p.Trail = old.trail
886			}
887			return nil, false, err
888		}
889		return res, false, nil
890	}
891	
892	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
893	//
894	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
895	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
896	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
897	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
898	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
899	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
900	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
901	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
902		if saved, ok := s.data.Returns[request]; ok {
903			if saved.Handoff == handoffReq && saved.Reason == reason {
904				return saved, true, nil
905			}
906			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
907				request, saved.Handoff, saved.Reason)
908		}
909	
910		h, ok := s.data.Handoffs[handoffReq]
911		if !ok {
912			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
913		}
914		if h.ReturnedBy != "" {
915			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
916		}
917	
918		// 先做全部校验，任何一件不满足都整批拒绝。
919		for _, id := range h.Parcels {
920			p, ok := s.data.Parcels[id]
921			if !ok {
922				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
923			}
924			if inc := activeFreeze(p); inc != "" {
925				return nil, false, fmt.Errorf("退回失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批退回拒绝，整批退回未执行", id, inc)
926			}
927			if p.Station != h.To || p.Status != statusInStation {
928				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
929					id, p.Station, p.Status, h.To)
930			}
931			last := lastFlowEvent(p.Trail)
932			if last.Op != "交接" || last.Request != handoffReq {
933				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
934					id, handoffReq)
935			}
936		}
937	
938		res := &ReturnResult{
939			Request: request,
940			Handoff: handoffReq,
941			From:    h.To,
942			To:      h.From,
943			Reason:  reason,
944			Parcels: append([]string(nil), h.Parcels...),
945			Time:    now,
946		}
947		s.data.Returns[request] = res
948		h.ReturnedBy = request
949	
950		// 记录旧值，落盘失败时整体回滚。
951		prev := make(map[string]struct {
952			station string
953			trail   []Event
954		}, len(h.Parcels))
955		for _, id := range h.Parcels {
956			p := s.data.Parcels[id]
957			prev[id] = struct {
958				station string
959				trail   []Event
960			}{p.Station, append([]Event(nil), p.Trail...)}
961			p.Station = h.From
962			p.Status = statusInStation
963			p.Trail = append(p.Trail, Event{
964				Op:         "退回",
965				Station:    h.From,
966				From:       h.To,
967				Request:    request,
968				RefRequest: handoffReq,
969				Reason:     reason,
970				Time:       now,
971			})
972		}
973	
974		if err := s.save(); err != nil {
975			delete(s.data.Returns, request)
976			h.ReturnedBy = ""
977			for id, old := range prev {
978				p := s.data.Parcels[id]
979				p.Station = old.station
980				p.Trail = old.trail
981			}
982			return nil, false, err
983		}
984		return res, false, nil
985	}
