987	// Dispatch 提交一次配送批次出站。
988	//
989	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
990	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
991	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
992	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
993	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
994	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
995		if saved, ok := s.data.Batches[batch]; ok {
996			if saved.RelayedFrom != "" {
997				return nil, false, fmt.Errorf("批次号 %q 已由续接 %q 创建（来源批次 %q），不能用于出站，内容冲突",
998					batch, saved.RelayRequest, saved.RelayedFrom)
999			}
1000			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
1001				return saved, true, nil
1002			}
1003			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
1004		}
1005	
1006		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
1007		for _, id := range parcels {
1008			p, ok := s.data.Parcels[id]
1009			if !ok {
1010				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
1011			}
1012			if p.Station != station {
1013				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
1014			}
1015			if inc := activeFreeze(p); inc != "" {
1016				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
1017			}
1018			if p.Status != statusInStation {
1019				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
1020			}
1021		}
1022	
1023		res := &BatchResult{
1024			Batch:    batch,
1025			Station:  station,
1026			Courier:  courier,
1027			Parcels:  append([]string(nil), parcels...),
1028			Time:     now,
1029			Receipts: map[string]*ReceiptEntry{},
1030		}
1031		s.data.Batches[batch] = res
1032	
1033		// 记录旧值，落盘失败时整体回滚。
1034		prev := make(map[string]struct {
1035			status string
1036			trail  []Event
1037		}, len(parcels))
1038		for _, id := range parcels {
1039			p := s.data.Parcels[id]
1040			prev[id] = struct {
1041				status string
1042				trail  []Event
1043			}{p.Status, append([]Event(nil), p.Trail...)}
1044			p.Status = statusDelivering // 站点不变，仍记出发站
1045			p.Trail = append(p.Trail, Event{
1046				Op:      "出站",
1047				Station: station,
1048				Batch:   batch,
1049				Courier: courier,
1050				Time:    now,
1051			})
1052		}
1053	
1054		if err := s.save(); err != nil {
1055			delete(s.data.Batches, batch)
1056			for id, old := range prev {
1057				p := s.data.Parcels[id]
1058				p.Status = old.status
1059				p.Trail = old.trail
1060			}
1061			return nil, false, err
1062		}
1063		return res, false, nil
1064	}
1065	
1066	// Receipt 提交一件包裹在某个配送批次下的回执。
1067	//
1068	// 首次回执：批次必须存在，包裹必须属于该批次、在该批次没有未撤销的回执，且当前仍在该批次
1069	// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
1070	// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
1071	// 原因（失败时）、请求号和时间的回执记录；全部成员均有未撤销回执后批次自动完成。
1072	// 已撤销的回执不再占用该件的回执名额，可用新请求号重新回执（见 RevokeReceipt）。
1073	// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
1074	// true，不重新检查当前状态，即使失败包裹已进入新批次或该回执已被撤销（重放不恢复回执，
1075	// 结果中可辨认已撤销）；请求号相同但内容不同报冲突。
1076	// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
1077	// 失败的首次回执不占用请求号。
1078	func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
1079		res, replayed, undo, err := s.applyReceipt(request, batch, parcel, result, reason, now)
1080		if err != nil || replayed {
1081			return res, replayed, err
1082		}
1083		if err := s.save(); err != nil {
1084			undo() // 落盘失败：回滚内存变更，保留原有有效数据
1085			return nil, false, err
1086		}
1087		return res, false, nil
1088	}
1089	
1090	// applyReceipt 在内存台账上校验并应用一条回执（不落盘），是 Receipt 与
1091	// ImportReceipts 共用的核心。全部校验通过后才会改动数据；返回的 undo 可在
1092	// 整体保存失败时撤销本次改动（重放或校验失败时 undo 为 nil）。
1093	func (s *Store) applyReceipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, undo func(), err error) {
1094		if saved, ok := s.data.Receipts[request]; ok {
1095			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
1096				return saved, true, nil, nil
1097			}
1098			return nil, false, nil, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
1099				request, saved.Batch, saved.Parcel, saved.Result)
1100		}
1101	
1102		b, ok := s.data.Batches[batch]
1103		if !ok {
1104			return nil, false, nil, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
1105		}
1106		member := false
1107		for _, id := range b.Parcels {
1108			if id == parcel {
1109				member = true
1110				break
1111			}
1112		}
1113		if !member {
1114			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
1115		}
1116		if e, done := b.Receipts[parcel]; done && e.RevokedBy == "" {
1117			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能有一条未撤销回执", parcel, batch)
1118		}
1119		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
1120		if p.Status != statusDelivering || currentBatch(p) != batch {
1121			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
1122		}
1123	
1124		res = &ReceiptResult{
1125			Request: request,
1126			Batch:   batch,
1127			Parcel:  parcel,
1128			Result:  result,
1129			Reason:  reason,
1130			Time:    now,
1131		}
1132		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
1133	
1134		// 记录旧值，undo 在整体落盘失败时回滚。
1135		oldStatus, oldStation := p.Status, p.Station
1136		oldTrailLen := len(p.Trail)
1137		oldEntry, hadEntry := b.Receipts[parcel] // 被取代的已撤销条目（若有）
1138	
1139		if result == resultSigned {
1140			p.Status = statusSigned // 站点保留不变
1141		} else {
1142			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
1143			p.Station = b.Station
1144		}
1145		p.Trail = append(p.Trail, Event{
1146			Op:      "回执",
1147			Station: p.Station,
1148			Batch:   batch,
1149			Result:  result,
1150			Reason:  reason,
1151			Request: request,
1152			Time:    now,
1153		})
1154		b.Receipts[parcel] = entry
1155		s.data.Receipts[request] = res
1156	
1157		undo = func() {
1158			delete(s.data.Receipts, request)
1159			if hadEntry {
1160				b.Receipts[parcel] = oldEntry
1161			} else {
1162				delete(b.Receipts, parcel)
1163			}
1164			p.Status, p.Station = oldStatus, oldStation
1165			p.Trail = p.Trail[:oldTrailLen]
1166		}
1167		return res, false, undo, nil
1168	}
