1228	// fork 返回当前台账的深拷贝副本，供整批导入试算；副本上的任何改动都不影响原台账。
1229	func (s *Store) fork() (*Store, error) {
1230		buf, err := json.Marshal(s.data)
1231		if err != nil {
1232			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1233		}
1234		var cp ledgerFile
1235		if err := json.Unmarshal(buf, &cp); err != nil {
1236			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1237		}
1238		return &Store{path: s.path, data: cp}, nil
1239	}
