1361	// Freeze 对一件在站包裹登记异常冻结。
1362	//
1363	// 首次冻结：包裹必须已登记、当前归属指定站点且状态为在站；配送中、已签收或已冻结的
1364	// 包裹不能冻结。成功后站点不变，状态转为异常冻结，追加一条含异常单号、原因、站点和
1365	// 时间的冻结记录。一件包裹同时只能有一张未解除异常单。
1366	// 冻结只是管理记录，不移动实物、不算新流转。
1367	// 异常单号标识一次异常，解除后也不能复用：相同异常单号且包裹、站点、清理后的原因
1368	// 相同，直接返回首次冻结结果与时间，replayed 为 true，不再次冻结（即使该异常单已解除、
1369	// 包裹已发生新的流转，也不检查当前状态）；异常单号相同但内容不同报冲突；
1370	// 失败的首次冻结不占用异常单号。异常单号与包裹编号及其他业务编号分属独立去重范围。
1371	func (s *Store) Freeze(incident, parcel, station, reason string, now time.Time) (res *FreezeResult, replayed bool, err error) {
1372		if saved, ok := s.data.Freezes[incident]; ok {
1373			if saved.Parcel == parcel && saved.Station == station && saved.Reason == reason {
1374				return saved, true, nil
1375			}
1376			return nil, false, fmt.Errorf("异常单号 %q 已用于一次不同的冻结（包裹=%q 站点=%q 原因=%q），内容冲突",
1377				incident, saved.Parcel, saved.Station, saved.Reason)
1378		}
1379	
1380		p, ok := s.data.Parcels[parcel]
1381		if !ok {
1382			return nil, false, fmt.Errorf("冻结失败：包裹 %q 未登记，冻结未执行", parcel)
1383		}
1384		if p.Station != station {
1385			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前归属 %q，不在指定站点 %q，冻结未执行", parcel, p.Station, station)
1386		}
1387		if p.Status != statusInStation {
1388			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前状态为 %q，仅在站包裹可以冻结，冻结未执行", parcel, p.Status)
1389		}
1390	
1391		res = &FreezeResult{
1392			Incident: incident,
1393			Parcel:   parcel,
1394			Station:  station,
1395			Reason:   reason,
1396			Time:     now,
1397		}
1398		s.data.Freezes[incident] = res
1399	
1400		// 记录旧值，落盘失败时整体回滚。
1401		oldStatus := p.Status
1402		oldTrail := append([]Event(nil), p.Trail...)
1403		p.Status = statusFrozen // 站点不变
1404		p.Trail = append(p.Trail, Event{
1405			Op:       "冻结",
1406			Station:  station,
1407			Incident: incident,
1408			Reason:   reason,
1409			Time:     now,
1410		})
1411	
1412		if err := s.save(); err != nil {
1413			delete(s.data.Freezes, incident)
1414			p.Status, p.Trail = oldStatus, oldTrail
1415			return nil, false, err
1416		}
1417		return res, false, nil
1418	}
