1420	// Unfreeze 解除一件包裹当前的异常冻结。
1421	//
1422	// 首次解除：异常单必须存在且尚未解除，并且仍是该包裹当前冻结对应的异常单；
1423	// 异常单不存在、已解除或对应关系不符均拒绝。成功后包裹在原站恢复在站，原异常单
1424	// 永久标记为已解除（异常单号不得复用），追加一条含异常单号、解除请求号、处理说明及
1425	// 时间的解除记录，原冻结记录不删改；之后可用新异常单再次冻结。
1426	// 解除只是管理记录，不移动实物、不算新流转。
1427	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名：相同解除请求号且异常单、
1428	// 处理说明相同，直接返回首次解除结果与时间，replayed 为 true，不检查当前状态，也不影响
1429	// 后来新建的异常单或后续流转；请求号相同但内容不同报冲突；失败的首次解除不占用请求号。
1430	func (s *Store) Unfreeze(request, incident, note string, now time.Time) (res *UnfreezeResult, replayed bool, err error) {
1431		if saved, ok := s.data.Unfreezes[request]; ok {
1432			if saved.Incident == incident && saved.Note == note {
1433				return saved, true, nil
1434			}
1435			return nil, false, fmt.Errorf("解除请求号 %q 已用于一次不同的解除（异常单=%q 处理说明=%q），内容冲突",
1436				request, saved.Incident, saved.Note)
1437		}
1438	
1439		f, ok := s.data.Freezes[incident]
1440		if !ok {
1441			return nil, false, fmt.Errorf("解除失败：异常单号 %q 不存在，解除未执行", incident)
1442		}
1443		if f.ReleasedBy != "" {
1444			return nil, false, fmt.Errorf("解除失败：异常单 %q 已解除（解除请求号 %q），不能重复解除", incident, f.ReleasedBy)
1445		}
1446		p, ok := s.data.Parcels[f.Parcel]
1447		if !ok {
1448			return nil, false, fmt.Errorf("解除失败：异常单 %q 对应的包裹 %q 不存在，解除未执行", incident, f.Parcel)
1449		}
1450		if p.Status != statusFrozen || activeFreeze(p) != incident {
1451			return nil, false, fmt.Errorf("解除失败：异常单 %q 不是包裹 %q 当前冻结对应的异常单（当前异常单 %q），解除未执行",
1452				incident, f.Parcel, activeFreeze(p))
1453		}
1454	
1455		res = &UnfreezeResult{
1456			Request:  request,
1457			Incident: incident,
1458			Parcel:   f.Parcel,
1459			Note:     note,
1460			Time:     now,
1461		}
1462		s.data.Unfreezes[request] = res
1463		f.ReleasedBy = request
1464	
1465		// 记录旧值，落盘失败时整体回滚。
1466		oldStatus := p.Status
1467		oldTrail := append([]Event(nil), p.Trail...)
1468		p.Status = statusInStation // 在原站恢复在站，站点不变
1469		p.Trail = append(p.Trail, Event{
1470			Op:       "解除冻结",
1471			Station:  f.Station,
1472			Incident: incident,
1473			Request:  request,
1474			Note:     note,
1475			Time:     now,
1476		})
1477	
1478		if err := s.save(); err != nil {
1479			delete(s.data.Unfreezes, request)
1480			f.ReleasedBy = ""
1481			p.Status, p.Trail = oldStatus, oldTrail
1482			return nil, false, err
1483		}
1484		return res, false, nil
1485	}
1486	
1487	// Abort 中止一个配送批次：配送员已将该批次全部尚未回执的包裹实物收回出发站。
1488	// 成员与站点取自原批次结果，不允许另选成员或站点。
1489	//
1490	// 首次中止：批次必须存在、尚未完成且未中止，且至少有一件未回执成员；这些成员
1491	// 必须仍在原批次配送中、归属出发站，任一不符整批拒绝、不作任何改动。已回执成员
1492	// 及其回执完全保留，即使它们已进入其他批次或被冻结也不阻止中止，不检查也不改变
1493	// 其当前状态。全部满足时按原成员顺序将全部未回执件恢复“在站”（站点为出发站），
1494	// 各追加一条含批次、中止请求号、原因、站点和时间的收回记录；收回不是失败回执，
1495	// 批次回执记录不变。中止永久关闭原批次，原成员顺序、配送员与出站时间保留不变。
1496	// 收回算新的流转，收回后不能退回出站前的旧交接；收回件可交接、冻结或再次出站，
1497	// 但不能首次回执旧批次（receipt 与 receipt-import 同样遵守）。
1498	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且批次、
1499	// 清理后的原因相同，直接返回首次收回集合与时间，replayed 为 true，不重新计算成员、
1500	// 不检查当前状态、不改写台账；请求号相同但批次或原因不同报冲突。
1501	// 每批只能成功中止一次：换请求号再中止或中止已正常完成的批次均拒绝；
1502	// 失败的首次中止不占用请求号。
1503	func (s *Store) Abort(request, batch, reason string, now time.Time) (res *AbortResult, replayed bool, err error) {
1504		if saved, ok := s.data.Aborts[request]; ok {
1505			if saved.Batch == batch && saved.Reason == reason {
1506				return saved, true, nil
1507			}
1508			return nil, false, fmt.Errorf("中止请求号 %q 已用于一次不同的中止（批次=%q 原因=%q），内容冲突",
1509				request, saved.Batch, saved.Reason)
1510		}
1511	
1512		b, ok := s.data.Batches[batch]
1513		if !ok {
1514			return nil, false, fmt.Errorf("中止失败：批次号 %q 不存在", batch)
1515		}
1516		if b.AbortedBy != "" {
1517			return nil, false, fmt.Errorf("中止失败：批次 %q 已中止（中止请求号 %q），每批只能成功中止一次", batch, b.AbortedBy)
1518		}
1519		if b.TransferredBy != "" {
1520			return nil, false, fmt.Errorf("中止失败：批次 %q 已转交（续接请求号 %q），不能中止", batch, b.TransferredBy)
1521		}
1522		if b.Done() {
1523			return nil, false, fmt.Errorf("中止失败：批次 %q 已全部回执完成，不能中止", batch)
1524		}
1525	
1526		// 按原成员顺序挑出全部未回执成员（批次未完成，必至少有一件）。
1527		recalled := make([]string, 0, len(b.Parcels)-len(b.Receipts))
1528		for _, pid := range b.Parcels {
1529			if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
1530				recalled = append(recalled, pid)
1531			}
1532		}
1533		if len(recalled) == 0 {
1534			return nil, false, fmt.Errorf("中止失败：批次 %q 没有未回执成员，不能中止", batch)
1535		}
1536	
1537		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
1538		for _, pid := range recalled {
1539			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
1540			if p.Status != statusDelivering || currentBatch(p) != batch || p.Station != b.Station {
1541				return nil, false, fmt.Errorf("中止失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批中止未执行",
1542					pid, p.Station, p.Status, batch, b.Station)
1543			}
1544		}
1545	
1546		res = &AbortResult{
1547			Request: request,
1548			Batch:   batch,
1549			Station: b.Station,
1550			Reason:  reason,
1551			Parcels: recalled,
1552			Time:    now,
1553		}
1554		s.data.Aborts[request] = res
1555		b.AbortedBy = request
1556	
1557		// 记录旧值，落盘失败时整体回滚。
1558		prev := make(map[string]struct {
1559			status string
1560			trail  []Event
1561		}, len(recalled))
1562		for _, pid := range recalled {
1563			p := s.data.Parcels[pid]
1564			prev[pid] = struct {
1565				status string
1566				trail  []Event
1567			}{p.Status, append([]Event(nil), p.Trail...)}
1568			p.Status = statusInStation // 实物已收回出发站，站点仍记出发站
1569			p.Trail = append(p.Trail, Event{
1570				Op:      "收回",
1571				Station: b.Station,
1572				Batch:   batch,
1573				Request: request,
1574				Reason:  reason,
1575				Time:    now,
1576			})
1577		}
1578	
1579		if err := s.save(); err != nil {
1580			delete(s.data.Aborts, request)
1581			b.AbortedBy = ""
1582			for pid, old := range prev {
1583				p := s.data.Parcels[pid]
1584				p.Status = old.status
1585				p.Trail = old.trail
1586			}
1587			return nil, false, err
1588		}
1589		return res, false, nil
1590	}
1591	
1592	// BatchAbort 返回一个配送批次的中止结果；批次不存在或未中止时返回 nil。
1593	func (s *Store) BatchAbort(batch string) *AbortResult {
1594		b, ok := s.data.Batches[batch]
1595		if !ok || b.AbortedBy == "" {
1596			return nil
1597		}
1598		return s.data.Aborts[b.AbortedBy]
1599	}
1600	
1601	// Transfer 把原批次全部尚未回执的包裹在配送途中整批交给另一配送员：
1602	// 新建批次继续配送，无需回站。成员与站点取自原批次，不允许另选成员或站点。
1603	//
1604	// 首次续接：原批次必须存在、仍开放（未中止、未转交）且有未回执成员；新批次号
1605	// 必须从未被出站或续接使用；新配送员必须与原配送员不同。未回执成员必须全部仍在
1606	// 原批次配送中且归属出发站，任一不符整批拒绝、不作任何改动。已回执成员不检查也
1607	// 不变更，其后续流转或冻结不阻止续接。全部满足时新批次按原成员顺序接纳全部未
1608	// 回执件，沿用出发站，记录新配送员及接手时间；包裹保持“配送中”及原站点，当前
1609	// 配送归属切换到新批次，各追加一条含请求号、前后批次、新配送员、站点、原因和
1610	// 时间的续接记录。原批次永久关闭为“已转交”，原成员、配送员、出站时间与真实
1611	// 回执保留不变；转交不算回执、收回或再次出站。续接算新的流转，续接后不能退回
1612	// 配送前的旧交接。
1613	// 续接请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且原批次、
1614	// 新批次、新配送员、清理后的原因相同，直接返回首次转交集合、续接信息及时间，
1615	// replayed 为 true，不检查现状、不重算成员、不改写台账；请求号相同但内容不同报
1616	// 冲突；失败的首次续接不占用请求号。
1617	func (s *Store) Transfer(request, fromBatch, toBatch, courier, reason string, now time.Time) (res *TransferResult, replayed bool, err error) {
1618		if saved, ok := s.data.Transfers[request]; ok {
1619			if saved.FromBatch == fromBatch && saved.ToBatch == toBatch && saved.ToCourier == courier && saved.Reason == reason {
1620				return saved, true, nil
1621			}
1622			return nil, false, fmt.Errorf("续接请求号 %q 已用于一次不同的续接（原批次=%q 新批次=%q 新配送员=%q），内容冲突",
1623				request, saved.FromBatch, saved.ToBatch, saved.ToCourier)
1624		}
1625	
1626		b, ok := s.data.Batches[fromBatch]
1627		if !ok {
1628			return nil, false, fmt.Errorf("续接失败：原批次号 %q 不存在", fromBatch)
1629		}
1630		if b.AbortedBy != "" {
1631			return nil, false, fmt.Errorf("续接失败：批次 %q 已中止（中止请求号 %q），不能续接", fromBatch, b.AbortedBy)
1632		}
1633		if b.TransferredBy != "" {
1634			return nil, false, fmt.Errorf("续接失败：批次 %q 已转交（续接请求号 %q），不能再次续接", fromBatch, b.TransferredBy)
1635		}
1636		if _, used := s.data.Batches[toBatch]; used {
1637			return nil, false, fmt.Errorf("续接失败：新批次号 %q 已被出站或续接使用，不能复用", toBatch)
1638		}
1639		if courier == b.Courier {
1640			return nil, false, fmt.Errorf("续接失败：新配送员 %q 不能与原批次 %q 的配送员相同", courier, fromBatch)
1641		}
1642	
1643		// 按原成员顺序挑出全部未回执成员（批次仍开放，必至少有一件）。
1644		moved := make([]string, 0, len(b.Parcels)-len(b.Receipts))
1645		for _, pid := range b.Parcels {
1646			if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
1647				moved = append(moved, pid)
1648			}
1649		}
1650		if len(moved) == 0 {
1651			return nil, false, fmt.Errorf("续接失败：批次 %q 没有未回执成员，不能续接", fromBatch)
1652		}
1653	
1654		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
1655		for _, pid := range moved {
1656			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
1657			if p.Status != statusDelivering || currentBatch(p) != fromBatch || p.Station != b.Station {
1658				return nil, false, fmt.Errorf("续接失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批续接未执行",
1659					pid, p.Station, p.Status, fromBatch, b.Station)
1660			}
1661		}
1662	
1663		res = &TransferResult{
1664			Request:     request,
1665			FromBatch:   fromBatch,
1666			ToBatch:     toBatch,
1667			Station:     b.Station,
1668			FromCourier: b.Courier,
1669			ToCourier:   courier,
1670			Reason:      reason,
1671			Parcels:     append([]string(nil), moved...),
1672			Time:        now,
1673		}
1674		s.data.Transfers[request] = res
1675		s.data.Batches[toBatch] = &BatchResult{
1676			Batch:        toBatch,
1677			Station:      b.Station,
1678			Courier:      courier,
1679			Parcels:      append([]string(nil), moved...),
1680			Time:         now,
1681			Receipts:     map[string]*ReceiptEntry{},
1682			RelayedFrom:  fromBatch,
1683			RelayRequest: request,
1684		}
1685		b.TransferredBy = request
1686	
1687		// 记录旧值，落盘失败时整体回滚。包裹保持“配送中”及原站点，只追加续接轨迹。
1688		prev := make(map[string][]Event, len(moved))
1689		for _, pid := range moved {
1690			p := s.data.Parcels[pid]
1691			prev[pid] = append([]Event(nil), p.Trail...)
1692			p.Trail = append(p.Trail, Event{
1693				Op:        "续接",
1694				Station:   b.Station,
1695				Batch:     toBatch,
1696				FromBatch: fromBatch,
1697				Courier:   courier,
1698				Request:   request,
1699				Reason:    reason,
1700				Time:      now,
1701			})
1702		}
1703	
1704		if err := s.save(); err != nil {
1705			delete(s.data.Transfers, request)
1706			delete(s.data.Batches, toBatch)
1707			b.TransferredBy = ""
1708			for pid, old := range prev {
1709				s.data.Parcels[pid].Trail = old
1710			}
1711			return nil, false, err
1712		}
1713		return res, false, nil
1714	}
1715	
1716	// BatchTransferSource 返回以该批次为原批次的续接结果；批次不存在或未转交时返回 nil。
1717	func (s *Store) BatchTransferSource(batch string) *TransferResult {
1718		b, ok := s.data.Batches[batch]
1719		if !ok || b.TransferredBy == "" {
1720			return nil
1721		}
1722		return s.data.Transfers[b.TransferredBy]
1723	}
1724	
1725	// TransferOf 按续接请求号返回续接结果；不存在时返回 nil。
1726	func (s *Store) TransferOf(request string) *TransferResult {
1727		return s.data.Transfers[request]
1728	}
1729	
1730	// currentBatch 返回包裹当前配送归属的批次号（最后一条出站或续接记录的批次）；
1731	// 不在配送中返回空。续接不新增出站记录，但会把当前配送归属切换到新批次。
1732	func currentBatch(p *Parcel) string {
1733		for i := len(p.Trail) - 1; i >= 0; i-- {
1734			if p.Trail[i].Op == "出站" || p.Trail[i].Op == "续接" {
1735				return p.Trail[i].Batch
1736			}
1737		}
1738		return ""
1739	}
1740	
1741	// activeFreeze 返回包裹当前未解除冻结对应的异常单号；未冻结返回空。
1742	// 冻结状态与轨迹成对追加，故当前状态为异常冻结时最后一条冻结记录即为当前异常单。
1743	func activeFreeze(p *Parcel) string {
1744		if p.Status != statusFrozen {
1745			return ""
1746		}
1747		for i := len(p.Trail) - 1; i >= 0; i-- {
1748			if p.Trail[i].Op == "冻结" {
1749				return p.Trail[i].Incident
1750			}
1751		}
1752		return ""
1753	}
1754	
1755	// lastFlowEvent 返回轨迹中最后一条真实流转记录（交接/退回/出站/回执/收回）。
1756	// 冻结与解除只是管理记录，不算新流转，判定旧交接可否退回时须跳过它们。
1757	func lastFlowEvent(trail []Event) Event {
1758		for i := len(trail) - 1; i >= 0; i-- {
1759			switch trail[i].Op {
1760			case "冻结", "解除冻结":
1761				continue
1762			default:
1763				return trail[i]
1764			}
1765		}
1766		return Event{}
1767	}
1768	
1769	// BatchQuery 返回一个配送批次的出站结果与逐件回执进度；批次不存在时报错。
1770	func (s *Store) BatchQuery(batch string) (*BatchResult, error) {
1771		b, ok := s.data.Batches[batch]
1772		if !ok {
1773			return nil, fmt.Errorf("批次 %q 不存在", batch)
1774		}
1775		return b, nil
1776	}
1777	
1778	// sameOrder 判断两个列表长度与逐元素顺序完全一致。
1779	func sameOrder(a, b []string) bool {
1780		if len(a) != len(b) {
1781			return false
1782		}
1783		for i := range a {
1784			if a[i] != b[i] {
1785				return false
1786			}
1787		}
1788		return true
1789	}
1790	
1791	// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
1792	func sameSet(a, b []string) bool {
1793		if len(a) != len(b) {
1794			return false
1795		}
1796		x := append([]string(nil), a...)
1797		y := append([]string(nil), b...)
1798		sort.Strings(x)
1799		sort.Strings(y)
1800		for i := range x {
1801			if x[i] != y[i] {
1802				return false
1803			}
1804		}
1805		return true
1806	}
1807	
1808	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
1809	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
1810	func (s *Store) save() error {
1811		if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
1812			return fmt.Errorf("保存数据文件失败: %w", err)
1813		}
1814		buf, err := json.MarshalIndent(s.data, "", "  ")
1815		if err != nil {
1816			return fmt.Errorf("保存数据文件失败: %w", err)
1817		}
1818		buf = append(buf, '\n')
1819	
1820		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
1821		if err != nil {
1822			return fmt.Errorf("保存数据文件失败: %w", err)
1823		}
1824		tmpName := tmp.Name()
1825		cleanup := func() { _ = os.Remove(tmpName) }
1826	
1827		if _, err := tmp.Write(buf); err != nil {
1828			_ = tmp.Close()
1829			cleanup()
1830			return fmt.Errorf("保存数据文件失败: %w", err)
1831		}
1832		if err := tmp.Sync(); err != nil {
1833			_ = tmp.Close()
1834			cleanup()
1835			return fmt.Errorf("保存数据文件失败: %w", err)
1836		}
1837		if err := tmp.Close(); err != nil {
1838			cleanup()
1839			return fmt.Errorf("保存数据文件失败: %w", err)
1840		}
1841	
1842		// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
1843		var check ledgerFile
1844		if err := json.Unmarshal(buf, &check); err != nil {
1845			cleanup()
1846			return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
1847		}
1848	
1849		if err := os.Rename(tmpName, s.path); err != nil {
1850			cleanup()
1851			return fmt.Errorf("保存数据文件失败: %w", err)
1852		}
1853		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1854			_ = dir.Sync()
1855			_ = dir.Close()
1856		}
1857		return nil
1858	}
1859

