449	// receiptFileRecord 是回执整批导入文件中的单条记录（JSON）。
450	type receiptFileRecord struct {
451		Request string `json:"request"`
452		Batch   string `json:"batch"`
453		Parcel  string `json:"parcel"`
454		Result  string `json:"result"`
455		Reason  string `json:"reason"`
456	}
457	
458	// loadReceiptImportFile 读取并解析回执整批导入文件。文件为有序且非空的
459	// JSON 数组，元素为 request/batch/parcel/result/reason 字段的对象；
460	// 文件只读，绝不改写。任一记录清洗后不合法或请求号在文件内重复，
461	// 都返回带记录位置的错误，整份不予导入。
462	func loadReceiptImportFile(path string) ([]ReceiptImportRecord, error) {
463		raw, err := os.ReadFile(path)
464		if err != nil {
465			return nil, fmt.Errorf("读取回执导入文件失败: %w", err)
466		}
467		dec := json.NewDecoder(bytes.NewReader(raw))
468		dec.DisallowUnknownFields()
469		var records []receiptFileRecord
470		if err := dec.Decode(&records); err != nil {
471			return nil, fmt.Errorf("解析回执导入文件失败: %w", err)
472		}
473		var extra any
474		if err := dec.Decode(&extra); err != io.EOF {
475			return nil, fmt.Errorf("解析回执导入文件失败: 回执列表之后存在多余内容")
476		}
477		if len(records) == 0 {
478			return nil, fmt.Errorf("回执导入文件必须是有序且非空的回执列表")
479		}
480	
481		clean := make([]ReceiptImportRecord, 0, len(records))
482		seen := make(map[string]bool, len(records))
483		for i, rawRec := range records {
484			rec, err := cleanReceiptImportRecord(rawRec)
485			if err != nil {
486				return nil, fmt.Errorf("第 %d 条记录: %w", i+1, err)
487			}
488			if seen[rec.Request] {
489				return nil, fmt.Errorf("第 %d 条记录: 回执请求号 %q 在文件内重复", i+1, rec.Request)
490			}
491			seen[rec.Request] = true
492			clean = append(clean, rec)
493		}
494		return clean, nil
495	}
496	
497	// cleanReceiptImportRecord 清洗并校验一条导入记录：各标识去除两端空白后不可为空；
498	// 结果为失败时必须给出清理后非空的原因，签收时不可带原因。
499	func cleanReceiptImportRecord(raw receiptFileRecord) (ReceiptImportRecord, error) {
500		var rec ReceiptImportRecord
501		var err error
502		if rec.Request, err = cleanID("回执请求号", raw.Request); err != nil {
503			return rec, err
504		}
505		if rec.Batch, err = cleanID("批次号", raw.Batch); err != nil {
506			return rec, err
507		}
508		if rec.Parcel, err = cleanID("包裹编号", raw.Parcel); err != nil {
509			return rec, err
510		}
511		if rec.Result, err = cleanID("回执结果", raw.Result); err != nil {
512			return rec, err
513		}
514		if rec.Result != resultSigned && rec.Result != resultFailed {
515			return rec, fmt.Errorf("回执结果只能是 %q 或 %q，得到 %q", resultSigned, resultFailed, rec.Result)
516		}
517		rec.Reason = strings.TrimSpace(raw.Reason)
518		if rec.Result == resultFailed && rec.Reason == "" {
519			return rec, fmt.Errorf("结果为失败时原因不可为空或仅含空白")
520		}
521		if rec.Result == resultSigned && rec.Reason != "" {
522			return rec, fmt.Errorf("结果为签收时不可带原因")
523		}
524		return rec, nil
525	}
