527	func cmdReceiptImport(dataFile string, argv []string, stdout, stderr io.Writer) int {
528		fs := newFlagSet("receipt-import", stderr)
529		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
530		file := fs.String("file", "", "回执导入文件路径（JSON 数组，只读，不会被修改）")
531		if ok, code := parseFlags(fs, argv, stdout, stderr, printReceiptImportHelp); !ok {
532			return code
533		}
534	
535		if strings.TrimSpace(*file) == "" {
536			fmt.Fprintf(stderr, "%s receipt-import: 选项 --file 需要一个非空的回执导入文件路径\n", appName)
537			return exitBusiness
538		}
539	
540		// 输入文件只读；读取、解析或清洗失败时整份不予导入。
541		records, err := loadReceiptImportFile(*file)
542		if err != nil {
543			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
544			return exitBusiness
545		}
546	
547		store, err := Open(dataFile)
548		if err != nil {
549			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
550			return exitBusiness
551		}
552		items, err := store.ImportReceipts(records, now())
553		if err != nil {
554			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
555			return exitBusiness
556		}
557	
558		replayed := 0
559		for _, it := range items {
560			if it.Replayed {
561				replayed++
562			}
563		}
564		fmt.Fprintf(stdout, "回执导入成功（共 %d 条：新增 %d 条，重放 %d 条）\n", len(items), len(items)-replayed, replayed)
565		for i, it := range items {
566			mark := "新增"
567			if it.Replayed {
568				mark = "重放（返回首次保存的结果）"
569			}
570			if it.Revoked {
571				mark += "，该回执已撤销"
572			}
573			line := fmt.Sprintf("  %d. 请求号: %s    批次号: %s    包裹编号: %s    结果: %s",
574				i+1, it.Record.Request, it.Record.Batch, it.Record.Parcel, it.Record.Result)
575			if it.Record.Result == resultFailed {
576				line += fmt.Sprintf("    原因: %s", it.Record.Reason)
577			}
578			fmt.Fprintf(stdout, "%s    标记: %s    时间: %s\n", line, mark, it.Time.Format(timeFmt))
579		}
580		return exitOK
581	}
