629	func cmdBatch(dataFile string, argv []string, stdout, stderr io.Writer) int {
630		fs := newFlagSet("batch", stderr)
631		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
632		id := fs.String("id", "", "要查询的配送批次号")
633		if ok, code := parseFlags(fs, argv, stdout, stderr, printBatchHelp); !ok {
634			return code
635		}
636	
637		cleanIDVal, err := cleanID("批次号", *id)
638		if err != nil {
639			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
640			return exitBusiness
641		}
642	
643		store, err := Open(dataFile)
644		if err != nil {
645			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
646			return exitBusiness
647		}
648		b, err := store.BatchQuery(cleanIDVal)
649		if err != nil {
650			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
651			return exitBusiness
652		}
653	
654		status := "配送中"
655		if b.Done() {
656			status = "已完成"
657		}
658		ab := store.BatchAbort(cleanIDVal)
659		if ab != nil {
660			status = "已中止"
661		}
662		tr := store.BatchTransferSource(cleanIDVal)
663		if tr != nil {
664			status = "已转交"
665		}
666		timeLabel := "出站时间"
667		if b.RelayedFrom != "" {
668			timeLabel = "接手时间"
669		}
670		fmt.Fprintf(stdout, "批次号: %s\n出发站: %s\n配送员: %s\n%s: %s\n批次状态: %s\n",
671			b.Batch, b.Station, b.Courier, timeLabel, b.Time.Format(timeFmt), status)
672		if b.RelayedFrom != "" {
673			src := store.TransferOf(b.RelayRequest)
674			fmt.Fprintf(stdout, "批次来源: 续接自批次 %s（原配送员: %s，续接请求号: %s）\n",
675				b.RelayedFrom, src.FromCourier, b.RelayRequest)
676		}
677		if ab != nil {
678			fmt.Fprintf(stdout, "中止请求号: %s\n中止原因: %s\n中止时间: %s\n",
679				ab.Request, ab.Reason, ab.Time.Format(timeFmt))
680		}
681		if tr != nil {
682			fmt.Fprintf(stdout, "转交去向: 批次 %s（新配送员: %s）\n续接请求号: %s\n续接原因: %s\n转交时间: %s\n",
683				tr.ToBatch, tr.ToCourier, tr.Request, tr.Reason, tr.Time.Format(timeFmt))
684		}
685		fmt.Fprintf(stdout, "逐件回执（%d/%d 已回执）:\n", b.Effective(), len(b.Parcels))
686		for _, pid := range b.Parcels {
687			e, ok := b.Receipts[pid]
688			if !ok || e.RevokedBy != "" {
689				switch {
690				case tr != nil:
691					fmt.Fprintf(stdout, "  - %s    已转交    去向批次: %s    续接请求号: %s    时间: %s\n",
692						pid, tr.ToBatch, tr.Request, tr.Time.Format(timeFmt))
693				case ab != nil:
694					fmt.Fprintf(stdout, "  - %s    已收回    中止请求号: %s    原因: %s    时间: %s\n",
695						pid, ab.Request, ab.Reason, ab.Time.Format(timeFmt))
696				case ok:
697					fmt.Fprintf(stdout, "  - %s    未回执（原回执 %s 已撤销，撤销请求号: %s）\n", pid, e.Request, e.RevokedBy)
698				default:
699					fmt.Fprintf(stdout, "  - %s    未回执\n", pid)
700				}
701				continue
702			}
703			if e.Result == resultFailed {
704				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    原因: %s    请求号: %s    时间: %s\n",
705					pid, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt))
706			} else {
707				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    请求号: %s    时间: %s\n",
708					pid, e.Result, e.Request, e.Time.Format(timeFmt))
709			}
710		}
711		if rvs := store.BatchRevokes(cleanIDVal); len(rvs) > 0 {
712			fmt.Fprintf(stdout, "撤销记录（%d 条）:\n", len(rvs))
713			for _, rv := range rvs {
714				fmt.Fprintf(stdout, "  - 撤销请求号: %s    原回执请求号: %s    包裹: %s    批次: %s    原因: %s    时间: %s\n",
715					rv.Request, rv.Receipt, rv.Parcel, rv.Batch, rv.Reason, rv.Time.Format(timeFmt))
716			}
717		}
718		return exitOK
719	}
