		t.Fatalf("收件记录不符: %+v", p.Trail)
	}

	got, err := s.Query("P001")
	if err != nil {
		t.Fatalf("Query 失败: %v", err)
	}
	if got.Station != "站点A" || len(got.Trail) != 1 {
		t.Fatalf("查询结果不符: %+v", got)
	}

	if _, err := s.Query("NOPE"); !errors.Is(err, ErrNotFound) {
